using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class WisławaSzymborska
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Natchnienie, czymkolwiek ono jest, rodzi się z bezustannego ''nie wiem''.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Wszelka wiedza, która nie wyłania z siebie nowych pytań, staje się w szybkim czasie martwa.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Wygląda na to, że poeci będą mieli zawsze dużo roboty.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Sprawiasz wrażenie ducha, który próbuje wywołać żywych.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Świat mógł być odbierany jako świat szalony, a ja brałam go tylko na zwykły użytek.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Może to wszystko dzieje się w laboratorium? Pod jedną lampą w dzień i miliardami w nocy?", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nic darowane, wszystko pożyczone. Tonę w długach po uszy. Będę zmuszona sobą zapłacić za siebie, za życie oddać życie.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nie jest jak inne uczucia. Starsza i młodsza od nich równocześnie. Sama rodzi przyczyny, Które budzą ją do życia.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Umrzeć – tego się nie robi kotu. Bo co ma począć kot w pustym mieszkaniu.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Można nie kochać cię – i żyć, Ale nie można owocować.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Znam ludzi, którym w sercach zgasło, lecz mówią: ciepło nam i jasno, i bardzo kłamią, gdy się śmieją", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Historia zaokrągla szkielety do zera. Tysiąc i jeden to wciąż jeszcze tysiąc. Ten jeden, jakby go wcale nie było", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Mój wyścig z suknią nadal trwa. A jaki ona upór ma! A jak by ona chciała przeżyć!", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nikt w rodzinie nie umarł z miłości. Co tam było to było, ale nic dla mitu.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Bez mojej woli nawet liść nie spadnie ani źdźbło się nie ugnie pod kropką kopytka. Jest więc taki świat, nad którym los sprawuję niezależny? Czas, który wiążę łańcuchami znaków?", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Drogie syreny, tak musiało być, kochane fauny, wielmożne anioły, ewolucja stanowczo wyparła się was.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Radość pisania. Możność utrwalania. Zemsta ręki śmiertelnej.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Dopóki ta kobieta z Rijksmuseum w namalowanej ciszy i skupieniu mleko z dzbanka do miski dzień po dniu przelewa, nie zasługuje Świat na koniec Świata", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Jestem złą publicznością dla swojej pamięci. Chce, żebym bezustannie słuchała jej głosu, a ja się wiercę, chrząkam, słucham i nie słucham, wychodzę, wracam i znowu wychodzę.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nie wiem jak gdzie, ale tutaj na Ziemi jest sporo wszystkiego. Tutaj wytwarza się krzesła i smutki, nożyczki, skrzypce, czułość, tranzystory, zapory wodne, żarty, filiżanki.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "I cokolwiek uczynię, zmieni się na zawsze w to co uczyniłam.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Musi być do wyboru, Zmieniać się, żeby tylko nic się nie zmieniło.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nie znam roli, która gram, Wiem tylko, że jest moja, niewymienna", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Samokrytyczny szakal nie istnieje. Szarańcza, aligator, trychina i giez żyją jak żyją i rade są z tego.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Nic dwa razy się nie zdarza i nie zdarzy. Z tej przyczyny zrodziliśmy się bez wprawy i pomrzemy bez rutyny.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Tyle wiemy o sobie, ile nas sprawdzono. Mówię to wam ze swego nieznanego serca.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Czytamy listy umarłych jak bezradni bogowie, ale jednak bogowie, bo znamy późniejsze daty.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Jeśli istnieje waga, szale się nie chwieją. Jeśli jest sprawiedliwość, oto ona. Umrzeć ile konieczne, nie przebrawszy miary. Odrosnąć ile trzeba z ocalonej reszty.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Przepaść nas nie przecina. Przepaść nas otacza.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Czasem to wielki pech być nieboszczykiem.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Człowiek, który nie poczuł smaku swoich łez – nie jest prawdziwym człowiekiem.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Czytanie książek to najpiękniejsza zabawa, jaką sobie ludzkość wymyśliła.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Ktoś powiedział, że ludzie głupieją hurtowo i mądrzeją detalicznie. Dlatego kochamy i popieramy przypadki detaliczne.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Świat jest tak wielki, że wszystko jest szczegółem.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Umarłych wieczność dotąd trwa, dokąd pamięcią im się płaci.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Większość ludzi nie zawraca sobie głowy samodzielnym myśleniem – bo nie może albo nie chce – i w rezultacie łatwo pada ofiarą zbiorowych sugestii.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Żegnamy się dzisiaj z poetą, ale nie żegnamy się z jego poezją. Ona nas wszystkich tutaj obecnych i wszystkich nieobecnych, przeżyje na pewno.", Author = "Wisława Szymborska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Wisława_Szymborska", Text = "Życie pisze najbardziej oryginalne, najbardziej komiczne a jednocześnie najbardziej dramatyczne scenariusze.", Author = "Wisława Szymborska" },
        };
    }
}